-- Migration 436: AA-1116 (S282) — the option B billing policies as settings-registry keys (CIS 407; tech lead S279 and
-- 16/11/2026: every price, threshold, limit and policy value is data an administrator edits, never a code literal).
--
-- Why. The S282 pricing gap audit found the option B policies only in the ADR or as code constants: the 14-day trial
-- (add-ons included), TRIAL_DAYS_MAX = 60 (services/tenant_account/provision.py), the 50 % AI budget while trialing
-- (nowhere), the free pilot (nowhere: Booking drafts a pilot at full price), PILOT_MAX_WEEKS = 8 (dev_guard.py and the
-- provision API's le=8), the AI alert / stop at 80 / 100 % with a hard stop (shared/cost_guard.py PLAN_ALERT_PCT /
-- PLAN_APPROVAL_PCT, and 100 / 150 / hard stop off as the defaults of a new per-tenant budget row), and the commercial
-- terms (annual 10 of 12 months, founding 30 % for 12 months to at most 10 agencies on Growth / Business / CRM / TP,
-- combo 10 % on content + crm + tripplanner, FX reference 26,000 VND per USD, VND review every 3 months, a 12-month
-- price lock, a list-price review after 12 months).
--
-- What:
--   1. Nineteen rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py
--      into shared/settings/compiled_defaults.json in this PR), app cis, scope platform, maker-checker, no evidence,
--      no env override, enforced (services/tenant_account/pricing_settings.py names every key in this PR, the
--      settings-lint reader check; the AA-1116 code PRs read them through it, and the SQL readers of 437 / 438 through
--      shared.v_setting_billing_effective). Seeded at the option B values:
--        area billing: trial_days_default 14, trial_days_max 60, trial_ai_budget_pct 50, pilot_free true,
--          ai_alert_pct_default 80, ai_approval_pct_default 100, ai_hard_stop_default true, annual_paid_months 10,
--          founding_discount_pct 30, founding_months 12, founding_max_agencies 10, founding_eligible_plans
--          [content.growth, content.business, crm.*, tripplanner.*], combo_discount_pct 10, combo_products
--          [content, crm, tripplanner], fx_vnd_per_usd 26000, vnd_price_review_months 3, price_lock_months 12,
--          price_review_months 12;
--        area tenant: cis.tenant.pilot_max_weeks 8 (a pilot without an end date stays allowed, 435).
--      Each seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. Register 436.
--
-- Behaviour on apply. 437 and 438 read trial_ai_budget_pct and pilot_free through shared.v_setting_billing_effective (the
-- defaults until an administrator approves another value). No value row is seeded; the Python readers fall back to the
-- compiled defaults, so the code PRs work whether the file is applied or not.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: the AA-1116 migration-only PR (435-439, one batch), applied on Dev by Infra Migration Apply when the job
-- tables are idle (ADR 0017a). DM-6.1: no personal data. DM-7.1: no new table.
--
-- Number. 435 + 1 (see 435 for the renumber rule).
--
-- Locks. One INSERT of nineteen rows (the definition guard trigger allows the file's role, cis_owner). lock_timeout 5s.
-- Idempotent (ON CONFLICT (key) DO NOTHING), one transaction, self-registering.
--
-- Rollback (a new forward migration, after the code PRs are reverted): DELETE the keys' value rows first, then the
-- keys (437 / 438 must be rolled back first: they read two of them).

BEGIN;
SET LOCAL lock_timeout = '5s';

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM shared.schema_versions WHERE version = '435') THEN
        RAISE EXCEPTION 'migration 436: apply 435 first';
    END IF;
END $$;

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.billing.trial_days_default", "app": "cis", "area": "billing", "label": "Trial length for a new account or add-on (days)", "description": "The trial length the tenant_provision saga uses when staff create an account or attach an add-on without typing a trial length, and the trial an approved add-on request starts (services/tenant_account/provision.py). Option B: 14 days, add-ons included.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 60, "allowed_values": null, "default_value": 14, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days a new agency account, an add-on attached later, or an add-on request approved by staff runs as a free trial before billing starts.", "raise": "Longer trials: agencies have more time to try before paying; revenue starts later.", "lower": "Shorter trials: billing starts sooner; agencies may not finish setting up in time.", "when": "Change it when the sales offer changes or agencies keep asking for more time to try.", "example": "With the default of 14 days, an add-on attached on 1 March is billed from 15 March."}, "vi": {"what": "Số ngày dùng thử miễn phí của tài khoản đại lý mới, của add-on gắn sau, hoặc của yêu cầu add-on được nhân viên duyệt, trước khi bắt đầu tính phí.", "raise": "Dùng thử dài hơn: đại lý có thêm thời gian thử trước khi trả tiền; doanh thu bắt đầu muộn hơn.", "lower": "Dùng thử ngắn hơn: tính phí sớm hơn; đại lý có thể chưa kịp cài đặt xong.", "when": "Đổi khi chính sách bán hàng đổi hoặc đại lý thường xin thêm thời gian dùng thử.", "example": "Với mặc định 14 ngày, add-on gắn ngày 1/3 được tính phí từ ngày 15/3."}}},
{"key": "cis.billing.trial_days_max", "app": "cis", "area": "billing", "label": "Longest trial staff may give (days)", "description": "The longest trial_days the provision API accepts (422 above it); replaces the code constant TRIAL_DAYS_MAX of services/tenant_account/provision.py.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 365, "allowed_values": null, "default_value": 60, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The longest free trial staff may type when they create an account or attach an add-on; a longer request is refused.", "raise": "Staff can give longer trials, for example to a large prospect.", "lower": "Trials stay short; a long trial needs this value raised first.", "when": "Raise it for a special sales campaign; lower it when trials are being given too freely.", "example": "With the default of 60 days, a request for a 90-day trial is refused."}, "vi": {"what": "Thời gian dùng thử dài nhất nhân viên được nhập khi tạo tài khoản hoặc gắn add-on; yêu cầu dài hơn bị từ chối.", "raise": "Nhân viên có thể cho dùng thử lâu hơn, ví dụ cho một khách hàng tiềm năng lớn.", "lower": "Dùng thử luôn ngắn; muốn dùng thử lâu phải tăng giá trị này trước.", "when": "Tăng cho một đợt khuyến mãi đặc biệt; giảm khi dùng thử bị cho quá dễ dãi.", "example": "Với mặc định 60 ngày, yêu cầu dùng thử 90 ngày bị từ chối."}}},
{"key": "cis.billing.trial_ai_budget_pct", "app": "cis", "area": "billing", "label": "AI budget share during a trial (%)", "description": "While a subscription is trialing, the resolver (shared.v_tenant_entitlement_resolved, CIS 437) serves this share of its own AI budget part (the content plan's ai.budget_usd_monthly, the TripPlanner / CRM plan's ai.budget_addon_usd_monthly). Never applied to an override or a per-tenant AI budget row. Ends with the trial (no hand-made override to remove).", "value_type": "pct", "unit": "%", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 50, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The share of the plan's monthly AI budget a trialing agency may spend; the full budget starts when the trial converts.", "raise": "Trial agencies can use more AI; the cost of agencies that never pay grows.", "lower": "Trial agencies hit the AI limit sooner and may judge the product on a limited trial.", "when": "Raise it when trial agencies run out of AI before they can judge the product; lower it when trial AI cost is high and few trials convert.", "example": "With the default of 50 %, a trialing Growth agency (40 USD a month) may spend 20 USD of AI."}, "vi": {"what": "Tỷ lệ ngân sách AI hằng tháng của gói mà đại lý đang dùng thử được dùng; đủ ngân sách khi chuyển sang trả phí.", "raise": "Đại lý dùng thử được dùng AI nhiều hơn; chi phí cho đại lý không trả tiền tăng.", "lower": "Đại lý dùng thử chạm trần AI sớm hơn và có thể đánh giá sản phẩm qua bản thử bị giới hạn.", "when": "Tăng khi đại lý dùng thử hết AI trước khi kịp đánh giá; giảm khi chi phí AI dùng thử cao mà ít đại lý trả tiền.", "example": "Với mặc định 50 %, đại lý Growth đang dùng thử (40 USD một tháng) được dùng 20 USD AI."}}},
{"key": "cis.billing.pilot_free", "app": "cis", "area": "billing", "label": "Pilot agencies are not invoiced", "description": "When on, catalog.v_tenant_billing_v1.bill_free is true for a pilot agency (shared.tenants.is_pilot), so the Booking monthly software draft skips it until the pilot ends (End pilot in Tenant 360).", "value_type": "bool", "unit": null, "min_value": null, "max_value": null, "allowed_values": null, "default_value": true, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Whether pilot agencies use the products free until the pilot ends (End pilot on Tenant 360).", "raise": "Turn on: pilot agencies get no software invoice while the pilot lasts.", "lower": "Turn off: pilot agencies are invoiced like everyone else; tell them first.", "when": "Turn it off only if pilots are to be charged, for example after the launch offer ends.", "example": "With the default of on, a pilot agency gets no monthly software invoice until staff end its pilot."}, "vi": {"what": "Đại lý pilot có được dùng sản phẩm miễn phí cho tới khi kết thúc pilot (End pilot ở Tenant 360) hay không.", "raise": "Bật: đại lý pilot không nhận hoá đơn phần mềm trong thời gian pilot.", "lower": "Tắt: đại lý pilot bị lập hoá đơn như mọi đại lý khác; cần báo trước cho họ.", "when": "Chỉ tắt khi quyết định thu phí pilot, ví dụ sau khi ưu đãi ra mắt kết thúc.", "example": "Với mặc định bật, đại lý pilot không nhận hoá đơn phần mềm hằng tháng cho tới khi nhân viên kết thúc pilot."}}},
{"key": "cis.tenant.pilot_max_weeks", "app": "cis", "area": "tenant", "label": "Longest dated pilot (weeks)", "description": "The most weeks pilot_weeks may give when staff create a pilot agency with an end date (replaces the code constant PILOT_MAX_WEEKS of services/tenant_account/dev_guard.py and the le=8 bound of the provision API). A pilot without an end date ('until go-live') is always allowed.", "value_type": "int", "unit": "weeks", "min_value": 1, "max_value": 104, "allowed_values": null, "default_value": 8, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The longest end date staff may give a pilot agency when they create it; a pilot can also run with no end date until go-live.", "raise": "Staff can give pilots a later end date.", "lower": "Dated pilots stay short; longer ones run without a date and are ended by hand.", "when": "Raise it when pilots routinely need more time before go-live.", "example": "With the default of 8 weeks, a pilot created on 1 March may end on 26 April at the latest."}, "vi": {"what": "Ngày kết thúc xa nhất nhân viên được đặt cho đại lý pilot khi tạo; pilot cũng có thể không có ngày kết thúc và chạy tới khi go-live.", "raise": "Nhân viên có thể đặt ngày kết thúc pilot xa hơn.", "lower": "Pilot có hạn luôn ngắn; pilot dài hơn chạy không có ngày và được kết thúc bằng tay.", "when": "Tăng khi pilot thường cần thêm thời gian trước go-live.", "example": "Với mặc định 8 tuần, pilot tạo ngày 1/3 kết thúc muộn nhất ngày 26/4."}}},
{"key": "cis.billing.ai_alert_pct_default", "app": "cis", "area": "billing", "label": "AI budget alert at (% of the budget)", "description": "The share of the monthly AI budget at which a tenant without its own AI budget row is alerted (shared/cost_guard.py, replaces PLAN_ALERT_PCT); also the starting value when staff create a tenant AI budget row.", "value_type": "pct", "unit": "%", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 80, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "At what share of an agency's monthly AI budget the platform raises an alert to staff and the agency.", "raise": "Alerts come later, closer to the limit.", "lower": "Alerts come earlier and more often.", "when": "Lower it when agencies are surprised by the limit; raise it when alerts are noise.", "example": "With the default of 80 %, an agency with a 40 USD budget is alerted at 32 USD."}, "vi": {"what": "Ở mức bao nhiêu phần trăm ngân sách AI hằng tháng của đại lý thì nền tảng báo cho nhân viên và đại lý.", "raise": "Cảnh báo đến muộn hơn, sát giới hạn hơn.", "lower": "Cảnh báo đến sớm hơn và thường xuyên hơn.", "when": "Giảm khi đại lý bất ngờ vì chạm giới hạn; tăng khi cảnh báo thành nhiễu.", "example": "Với mặc định 80 %, đại lý có ngân sách 40 USD được báo khi đã dùng 32 USD."}}},
{"key": "cis.billing.ai_approval_pct_default", "app": "cis", "area": "billing", "label": "AI budget stop at (% of the budget)", "description": "The share of the monthly AI budget at which AI calls of a tenant without its own AI budget row stop or wait for approval (shared/cost_guard.py, replaces PLAN_APPROVAL_PCT); also the starting value of a new tenant AI budget row (it was 150 there).", "value_type": "pct", "unit": "%", "min_value": 50, "max_value": 300, "allowed_values": null, "default_value": 100, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "At what share of an agency's monthly AI budget its AI writing stops (or waits for staff approval when the hard stop is off).", "raise": "Agencies may spend past their budget before AI stops; AA carries the extra cost.", "lower": "AI stops before the budget is used up.", "when": "Raise it only for a short period when agencies must finish urgent work; keep 100 % otherwise.", "example": "With the default of 100 %, AI stops when an agency has spent its whole monthly budget."}, "vi": {"what": "Ở mức bao nhiêu phần trăm ngân sách AI hằng tháng thì việc viết bằng AI của đại lý dừng lại (hoặc chờ nhân viên duyệt khi tắt dừng cứng).", "raise": "Đại lý có thể dùng vượt ngân sách trước khi AI dừng; AA chịu phần chi phí vượt.", "lower": "AI dừng trước khi dùng hết ngân sách.", "when": "Chỉ tăng trong thời gian ngắn khi đại lý cần hoàn thành việc gấp; còn lại giữ 100 %.", "example": "Với mặc định 100 %, AI dừng khi đại lý đã dùng hết ngân sách tháng."}}},
{"key": "cis.billing.ai_hard_stop_default", "app": "cis", "area": "billing", "label": "AI stops hard at the budget", "description": "When on, a tenant without its own AI budget row has its AI calls refused at the stop share (shared/cost_guard.py); when off, they wait for staff approval. Also the starting value of a new tenant AI budget row.", "value_type": "bool", "unit": null, "min_value": null, "max_value": null, "allowed_values": null, "default_value": true, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Whether an agency's AI writing is refused outright at its budget, or waits for staff to approve more.", "raise": "Turn on: AI stops at the budget; no surprise cost.", "lower": "Turn off: AI calls wait for a staff approval instead of failing; someone must watch the queue.", "when": "Turn off when staff can approve extra AI quickly and agencies prefer waiting to failing.", "example": "With the default of on, an agency at its budget gets a clear 'AI budget reached' message."}, "vi": {"what": "AI của đại lý bị từ chối ngay khi chạm ngân sách, hay chờ nhân viên duyệt thêm.", "raise": "Bật: AI dừng ở mức ngân sách; không phát sinh chi phí bất ngờ.", "lower": "Tắt: lời gọi AI chờ nhân viên duyệt thay vì lỗi; cần có người theo dõi hàng chờ.", "when": "Tắt khi nhân viên duyệt thêm AI nhanh và đại lý thích chờ hơn là bị lỗi.", "example": "Với mặc định bật, đại lý chạm ngân sách nhận thông báo rõ 'đã hết ngân sách AI'."}}},
{"key": "cis.billing.annual_paid_months", "app": "cis", "area": "billing", "label": "Annual plan: months paid of 12", "description": "An annual subscription (tenant_subscription.billing_interval year) pays this many months for 12 (services/tenant_account/quote.py). Option B: 12 months for the price of 10.", "value_type": "int", "unit": "months", "min_value": 1, "max_value": 12, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many monthly prices an agency pays for a year when it pays annually.", "raise": "The annual discount gets smaller.", "lower": "The annual discount gets larger; less revenue per annual agency.", "when": "Change it with the sales offer; existing annual agencies keep their agreed price.", "example": "With the default of 10, a 349 USD plan paid yearly costs 3,490 USD."}, "vi": {"what": "Đại lý trả theo năm thì trả bao nhiêu tháng giá cho 12 tháng.", "raise": "Ưu đãi trả năm nhỏ lại.", "lower": "Ưu đãi trả năm lớn hơn; doanh thu mỗi đại lý trả năm ít hơn.", "when": "Đổi theo chính sách bán hàng; đại lý đang trả năm giữ giá đã thoả thuận.", "example": "Với mặc định 10, gói 349 USD trả năm có giá 3.490 USD."}}},
{"key": "cis.billing.founding_discount_pct", "app": "cis", "area": "billing", "label": "Founding agency discount (%)", "description": "The discount of the founding-agency offer (shared.tenants.founding_offer_from / _until) on eligible plans (services/tenant_account/quote.py). Does not stack with the combo discount: the better one applies.", "value_type": "pct", "unit": "%", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 30, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The discount the first agencies get on eligible plans while their founding offer lasts.", "raise": "Founding agencies pay less; more revenue is given up.", "lower": "Founding agencies pay closer to list price; the offer is less attractive.", "when": "Change it only for new founding agencies; agencies already on the offer keep what they agreed.", "example": "With the default of 30 %, a founding agency on a 349 USD plan pays 244.30 USD a month."}, "vi": {"what": "Mức giảm giá các đại lý đầu tiên nhận trên những gói đủ điều kiện trong thời gian ưu đãi sáng lập.", "raise": "Đại lý sáng lập trả ít hơn; bỏ lại nhiều doanh thu hơn.", "lower": "Đại lý sáng lập trả gần giá niêm yết hơn; ưu đãi kém hấp dẫn hơn.", "when": "Chỉ đổi cho đại lý sáng lập mới; đại lý đã nhận ưu đãi giữ mức đã thoả thuận.", "example": "Với mặc định 30 %, đại lý sáng lập dùng gói 349 USD trả 244,30 USD mỗi tháng."}}},
{"key": "cis.billing.founding_months", "app": "cis", "area": "billing", "label": "Founding offer length (months)", "description": "How long the founding-agency offer lasts from its start (Tenant 360 fills founding_offer_until from it).", "value_type": "int", "unit": "months", "min_value": 1, "max_value": 36, "allowed_values": null, "default_value": 12, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many months a founding agency keeps its discount.", "raise": "Founding agencies keep the discount longer.", "lower": "The discount ends sooner and full price starts earlier.", "when": "Change it with the founding offer terms.", "example": "With the default of 12 months, an offer starting 1 March 2027 ends on 29 February 2028."}, "vi": {"what": "Đại lý sáng lập giữ ưu đãi trong bao nhiêu tháng.", "raise": "Đại lý sáng lập giữ ưu đãi lâu hơn.", "lower": "Ưu đãi hết sớm hơn và giá đầy đủ bắt đầu sớm hơn.", "when": "Đổi theo điều khoản ưu đãi sáng lập.", "example": "Với mặc định 12 tháng, ưu đãi bắt đầu ngày 1/3/2027 kết thúc ngày 29/2/2028."}}},
{"key": "cis.billing.founding_max_agencies", "app": "cis", "area": "billing", "label": "Founding offer: most agencies", "description": "How many agencies may hold the founding-agency offer; Tenant 360 refuses one more (409 founding_offer_full).", "value_type": "int", "unit": "agencies", "min_value": 0, "max_value": 1000, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many agencies may receive the founding-agency offer in total.", "raise": "More agencies can get the founding discount.", "lower": "Fewer agencies can get it; 0 closes the offer.", "when": "Raise it to extend the launch campaign; set 0 when the offer is over.", "example": "With the default of 10, staff cannot give the offer to an eleventh agency."}, "vi": {"what": "Tổng số đại lý được nhận ưu đãi sáng lập.", "raise": "Nhiều đại lý hơn được nhận giảm giá sáng lập.", "lower": "Ít đại lý hơn được nhận; 0 là đóng ưu đãi.", "when": "Tăng để kéo dài chiến dịch ra mắt; đặt 0 khi ưu đãi kết thúc.", "example": "Với mặc định 10, nhân viên không thể trao ưu đãi cho đại lý thứ mười một."}}},
{"key": "cis.billing.founding_eligible_plans", "app": "cis", "area": "billing", "label": "Founding offer: plans it covers", "description": "Plan keys the founding discount applies to; a product.* entry covers every plan of that product (services/tenant_account/quote.py). Option B: Growth, Business, every CRM and TripPlanner plan (Starter excluded).", "value_type": "list", "unit": null, "min_value": null, "max_value": null, "allowed_values": null, "default_value": ["content.growth", "content.business", "crm.*", "tripplanner.*"], "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Which plans the founding-agency discount applies to; an entry ending in .* covers every plan of a product.", "raise": "Adding plans: the discount covers more of the invoice.", "lower": "Removing plans: the discount covers less.", "when": "Change it when a plan joins or leaves the launch offer.", "example": "With the default list, Growth and Business are discounted but Starter is not."}, "vi": {"what": "Ưu đãi sáng lập áp dụng cho những gói nào; mục kết thúc bằng .* là mọi gói của một sản phẩm.", "raise": "Thêm gói: ưu đãi phủ nhiều phần hoá đơn hơn.", "lower": "Bớt gói: ưu đãi phủ ít hơn.", "when": "Đổi khi một gói được đưa vào hoặc rút khỏi ưu đãi ra mắt.", "example": "Với danh sách mặc định, Growth và Business được giảm còn Starter thì không."}}},
{"key": "cis.billing.combo_discount_pct", "app": "cis", "area": "billing", "label": "Combo discount (%)", "description": "The discount when an agency holds every product of cis.billing.combo_products (services/tenant_account/quote.py). Does not stack with the founding discount: the better one applies.", "value_type": "pct", "unit": "%", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The discount an agency gets on its whole software bill when it uses every product of the combo.", "raise": "Combos are cheaper; less revenue per combo agency.", "lower": "Combos are closer to the sum of list prices.", "when": "Change it with the sales offer.", "example": "With the default of 10 %, an agency paying 455 USD for three products pays 409.50 USD."}, "vi": {"what": "Mức giảm trên toàn bộ hoá đơn phần mềm khi đại lý dùng đủ các sản phẩm của combo.", "raise": "Combo rẻ hơn; doanh thu mỗi đại lý combo ít hơn.", "lower": "Combo gần bằng tổng giá niêm yết.", "when": "Đổi theo chính sách bán hàng.", "example": "Với mặc định 10 %, đại lý trả 455 USD cho ba sản phẩm chỉ trả 409,50 USD."}}},
{"key": "cis.billing.combo_products", "app": "cis", "area": "billing", "label": "Combo: products it needs", "description": "The products an agency must all hold (live) for the combo discount (services/tenant_account/quote.py).", "value_type": "list", "unit": null, "min_value": null, "max_value": null, "allowed_values": null, "default_value": ["content", "crm", "tripplanner"], "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Which products an agency must all use to get the combo discount.", "raise": "Adding a product: the combo is harder to reach.", "lower": "Removing a product: more agencies reach the combo.", "when": "Change it when a new product joins the bundle.", "example": "With the default list, an agency needs the Content studio, the CRM and TripPlanner."}, "vi": {"what": "Đại lý phải dùng đủ những sản phẩm nào để được giảm giá combo.", "raise": "Thêm sản phẩm: khó đạt combo hơn.", "lower": "Bớt sản phẩm: nhiều đại lý đạt combo hơn.", "when": "Đổi khi có sản phẩm mới vào gói.", "example": "Với danh sách mặc định, đại lý cần Content studio, CRM và TripPlanner."}}},
{"key": "cis.billing.fx_vnd_per_usd", "app": "cis", "area": "billing", "label": "Reference rate (VND per USD)", "description": "The reference exchange rate the Plans page compares the VND price list with (drift warning) and the quote uses to show a USD equivalent (services/tenant_account/quote.py). Not used to invoice: VND agencies pay the VND list price.", "value_type": "numeric", "unit": "VND/USD", "min_value": 1000, "max_value": 100000, "allowed_values": null, "default_value": 26000, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The exchange rate used to compare VND prices with USD prices and warn when they drift apart.", "raise": "VND prices look cheaper against USD; the drift warning may appear.", "lower": "VND prices look dearer against USD; the drift warning may appear.", "when": "Update it at each quarterly VND price review.", "example": "With the default of 26,000, a 349 USD plan is about 9,074,000 VND."}, "vi": {"what": "Tỷ giá dùng để so bảng giá VND với giá USD và cảnh báo khi hai bảng lệch nhau.", "raise": "Giá VND trông rẻ hơn so với USD; có thể hiện cảnh báo lệch.", "lower": "Giá VND trông đắt hơn so với USD; có thể hiện cảnh báo lệch.", "when": "Cập nhật ở mỗi lần xem lại giá VND hằng quý.", "example": "Với mặc định 26.000, gói 349 USD vào khoảng 9.074.000 VND."}}},
{"key": "cis.billing.vnd_price_review_months", "app": "cis", "area": "billing", "label": "Review VND prices every (months)", "description": "The Plans page marks a plan's VND price for review when price_set_at is older than this many months.", "value_type": "int", "unit": "months", "min_value": 1, "max_value": 24, "allowed_values": null, "default_value": 3, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How often the VND price list should be reviewed against the reference exchange rate.", "raise": "Reviews are less frequent.", "lower": "Reviews are more frequent.", "when": "Shorten it when the exchange rate moves fast.", "example": "With the default of 3 months, a VND price set on 1 January shows a review badge from 1 April."}, "vi": {"what": "Bao lâu nên xem lại bảng giá VND theo tỷ giá tham chiếu một lần.", "raise": "Xem lại thưa hơn.", "lower": "Xem lại dày hơn.", "when": "Rút ngắn khi tỷ giá biến động nhanh.", "example": "Với mặc định 3 tháng, giá VND đặt ngày 1/1 hiện nhãn cần xem lại từ ngày 1/4."}}},
{"key": "cis.billing.price_lock_months", "app": "cis", "area": "billing", "label": "Price lock for a new subscription (months)", "description": "When staff attach a plan, the agreed price is locked for this many months (agreed_until = start + this); 0 = no lock. Tenant 360 fills it; a later list-price change does not move a locked subscription.", "value_type": "int", "unit": "months", "min_value": 0, "max_value": 60, "allowed_values": null, "default_value": 12, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How long a new agency keeps the price it signed up at when list prices change later.", "raise": "Agencies are protected from price rises for longer.", "lower": "Price changes reach agencies sooner; 0 means no protection.", "when": "Change it with the sales terms.", "example": "With the default of 12 months, an agency that joins in March 2027 keeps its price until March 2028."}, "vi": {"what": "Đại lý mới giữ giá lúc đăng ký trong bao lâu khi giá niêm yết đổi về sau.", "raise": "Đại lý được bảo vệ khỏi tăng giá lâu hơn.", "lower": "Thay đổi giá tới đại lý sớm hơn; 0 là không bảo vệ.", "when": "Đổi theo điều khoản bán hàng.", "example": "Với mặc định 12 tháng, đại lý tham gia tháng 3/2027 giữ giá tới tháng 3/2028."}}},
{"key": "cis.billing.price_review_months", "app": "cis", "area": "billing", "label": "Review list prices every (months)", "description": "The Plans page marks a plan's list price for review when price_set_at is older than this many months (option B: the launch price is reviewed after 12 months).", "value_type": "int", "unit": "months", "min_value": 1, "max_value": 60, "allowed_values": null, "default_value": 12, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How often the list prices of the plans should be reviewed.", "raise": "Price reviews are less frequent.", "lower": "Price reviews are more frequent.", "when": "Shorten it while the market is still being tested.", "example": "With the default of 12 months, a price set on 1 March 2027 shows a review badge from 1 March 2028."}, "vi": {"what": "Bao lâu nên xem lại giá niêm yết của các gói một lần.", "raise": "Xem lại giá thưa hơn.", "lower": "Xem lại giá dày hơn.", "when": "Rút ngắn khi vẫn đang thử nghiệm thị trường.", "example": "Với mặc định 12 tháng, giá đặt ngày 1/3/2027 hiện nhãn cần xem lại từ ngày 1/3/2028."}}}
